pages={}
def add(path,title,desc,body,schema=None):pages[path]=(title,desc,body,schema)
def intro(k,t,d):return f'<section class="page-intro"><div class="eyebrow">{k}</div><h1>{t}</h1><p class="lead">{d}</p></section>'
def cta():return '<section class="cta"><div class="eyebrow">YOUR NEXT CHAPTER</div><h2>Let’s make<br>what’s next work.</h2><a class="button light" href="/contact/">Book a Strategy Call <span>↗</span></a><p>Vancouver roots. North American ambition.</p></section>'
def cards():return ''.join(f'<a class="service-row" href="/services/{s[0]}/"><span class="num">0{i+1}</span><h3>{s[1]}</h3><span class="arrow">↗</span><p>{s[3]}</p></a>' for i,s in enumerate(services))
def art(kind=''):return f'<div class="art {kind}" role="img" aria-label="Original geometric composition: two intersecting arcs representing marketing and engineering"><div class="orb a"></div><div class="orb b"></div><div class="art-grid"></div><span class="art-label">TWO DISCIPLINES.<br>ONE DIRECTION.</span><span class="coordinate">MM / 49.2827° N</span></div>'
works=[('search-to-signup','SaaS','SEO','Search to signup','A framework for connecting search intent to product activation.'),('product-to-platform','B2B Technology','Web Development','Product to platform','A framework for a clearer, faster product website.'),('click-to-customer','E-commerce','Paid Media','Click to customer','A framework for more accountable acquisition.')]
def workcards():return ''.join(f'<a class="work-card" href="/work/{slug}/" data-service="{svc}" data-industry="{ind}"><div class="work-art w{i}"><span>0{i+1} / MM</span><div></div><b>↗</b></div><div class="eyebrow">{ind} / {svc}</div><h3>{name}</h3><p>{desc}</p><small>CASE STUDY PLACEHOLDER — NOT CLIENT WORK</small></a>' for i,(slug,ind,svc,name,desc) in enumerate(works))
articles=[('seo-before-scale','SEO','Before you scale content, fix the foundations.','Map commercial intent, check indexability and make measurement useful.',['Audit the pages buyers need','Review crawling, indexation, canonical signals and internal links before increasing publishing volume.','Connect intent to a useful next step','Group searches by the decision a buyer is making. Give each priority page a clear purpose.','Measure business contribution','Track qualified enquiries alongside organic visibility. Annotate changes and compare like-for-like periods.']),('google-ads-saas','Paid Media','A better brief for your next Google Ads campaign.','Start with the customer, the economics and the conversion you can trust.',['Define a qualified conversion','Agree with sales on the lead criteria that matter before choosing campaign targets.','Match message to intent','Separate exploratory searches from high-intent evaluation. Align the ad, landing page and offer.','Build a learning budget','Set a test hypothesis, a review window and a decision rule before increasing investment.']),('performance-is-product','Engineering','Web performance is a product decision.','Treat speed as part of the buying experience, from the first request onward.',['Start with the critical journey','Identify the landing pages and interactions that determine whether a visitor can take the next step.','Set a performance budget','Control image weight, third-party scripts and font delivery. Test on a representative mobile device.','Measure real experience','Use field data when available. Review LCP, INP and CLS alongside accessibility and conversion behaviour.'])]
def insights():return ''.join(f'<a class="insight" href="/insights/{slug}/"><div class="eyebrow">{cat} / DRAFT OUTLINE</div><h3>{title}</h3><span>Read the outline ↗</span></a>' for slug,cat,title,desc,sections in articles)
add('/','Marketing and engineering under one roof','Montshire Media is a Vancouver marketing and technology agency for SaaS, startups and B2B technology companies.',f'''<section class="hero"><div class="hero-copy"><div class="eyebrow"><i></i> INDEPENDENT THINKING. CONNECTED EXECUTION.</div><h1>Marketing and<br>engineering.<br><em>Under one roof.</em></h1><p>For ambitious tech companies, growth works better when the people building the product understand the people buying it.</p><div class="actions"><a class="button" href="/contact/">Book a Strategy Call ↗</a><a class="text-link" href="/work/">Explore our approach ↗</a></div><div class="hero-bottom">VANCOUVER, CANADA <span>SERVING CANADA + THE US</span></div></div>{art()}</section><div class="ticker"><span>STRATEGY MEETS EXECUTION</span><b>✳</b><span>SEARCH MEETS PRODUCT</span><b>✳</b><span>IDEAS MEET EVIDENCE</span></div><section class="section split"><div class="eyebrow">01 / WHAT WE DO</div><div><h2>Built to connect.<br>Designed to grow.</h2><p class="lead">From the first search to the next product release, we bring the disciplines together around one business goal.</p></div></section><section class="services section">{cards()}</section><section class="section green"><div class="section-heading"><div><div class="eyebrow">02 / THE WORK</div><h2>Big questions.<br>Practical answers.</h2></div><p>Explore our case study formats.<br>Verified client work is coming next.</p></div><div class="work-grid">{workcards()}</div></section><section class="section split"><div><div class="eyebrow">03 / WHY MONTSHIRE</div><h2>Less handoff.<br>More forward.</h2></div><div class="principles"><article><h3>A shared brief.</h3><p>Marketing and engineering start with the same business problem, so the strategy survives the handoff.</p></article><article><h3>Senior-led thinking.</h3><p>Direct conversations, clear tradeoffs and a delivery plan you can interrogate.</p></article><article><h3>Evidence over theatre.</h3><p>Define success before work begins. Report what changed, what we learned and what happens next.</p></article></div></section><section class="section process-strip"><div class="eyebrow">04 / HOW WE WORK</div><h2>Clarity at every step.</h2><div class="steps">{''.join(f'<a href="/process/#step-{i}"><small>0{i}</small><h3>{x}</h3><span>↗</span></a>' for i,x in enumerate(['Discover','Strategy','Build','Launch','Optimize'],1))}</div></section><section class="section"><div class="section-heading"><div><div class="eyebrow">05 / POINT OF VIEW</div><h2>Thinking that<br>moves things.</h2></div><a href="/insights/" class="text-link">All insights ↗</a></div><div class="three">{insights()}</div></section>{cta()}''')
add('/services/','Services','SEO, paid media, web and mobile development, content and analytics for technology companies.',intro('OUR CAPABILITIES','Six disciplines.<br>One shared ambition.','Choose a focused engagement or connect the capabilities your next stage needs.')+f'<section class="section services">{cards()}</section>'+cta())
for slug,name,headline,desc,deliver,stack,kpi in services:
 faq=[('Where do we start?','With a discovery conversation, access review and a prioritized scope. Recommendations follow the evidence, not a preset package.'),('How is success measured?',f'We agree a baseline and reporting cadence around {kpi.lower()}. Targets are set after discovery; outcomes are never guaranteed.'),('Can you work with our team?','Yes. The engagement can complement your internal marketing, product and engineering teams, with responsibilities agreed before delivery.')]
 body=intro(name,headline,desc)+f'<section class="section split"><h2>The problem<br>behind the brief.</h2><div><p class="lead">Disconnected execution makes it hard to see what is working. We start by finding the constraint, then build a focused plan around it.</p><h3>Our approach</h3><p>Audit the current state. Agree the opportunity and the tradeoffs. Prioritize delivery in measurable increments, then use the results to choose the next step.</p></div></section><section class="section green"><h2>What we deliver.</h2><div class="deliverables">'+''.join(f'<div><span>↗</span><h3>{x.title()}</h3></div>' for x in deliver.split('|'))+f'</div></section><section class="section split"><div><div class="eyebrow">TOOLS, CHOSEN FOR THE JOB</div><h3>{stack}</h3><p>Final stack depends on your systems, requirements and budget.</p></div><div><div class="eyebrow">MEASUREMENT</div><h3>{kpi}</h3><p>Baselines and target values are agreed during discovery.</p></div></section><section class="section narrow"><h2>Good questions.</h2>'+''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in faq)+'</section>'+cta()
 add('/services/'+slug+'/',name+' agency in Vancouver',desc,body,{'@type':'FAQPage','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q,a in faq]})
add('/work/','Work and case studies','Explore the Montshire Media case study framework. Verified client work and results will be added before launch.',intro('WORK / A LOOK AHEAD','The thinking.<br>Then the proof.','These clearly marked templates show how we will document real engagements. They do not represent delivered client work.')+'<section class="section"><div class="filters"><label>Service<select id="service-filter"><option value="all">All services</option><option>SEO</option><option>Web Development</option><option>Paid Media</option></select></label><label>Industry<select id="industry-filter"><option value="all">All industries</option><option>SaaS</option><option>B2B Technology</option><option>E-commerce</option></select></label></div><p id="filter-status" aria-live="polite"></p><div class="work-grid">'+workcards()+'</div></section>'+cta())
for slug,ind,svc,title,desc in works:
 add('/work/'+slug+'/',title+' — case study placeholder',desc,intro('CASE STUDY PLACEHOLDER / '+ind,title,desc)+'<section class="section narrow"><p class="notice">[Case study placeholder: replace with real client work]. No client, outcome or quote is implied.</p>'+''.join(f'<article><h2>{label}</h2><p>[{copy}: to be supplied and approved by the client]</p></article>' for label,copy in [('Challenge','Client context and business constraint'),('Strategy','Research and strategic rationale'),('Execution','Scope, timeline and delivered work'),('Results','Verified metrics, baseline, period and attribution'),('Tech stack','Actual platforms and integrations')])+'<blockquote>[Testimonial: to be supplied, attributed and approved]</blockquote></section>'+cta())
add('/about/','About Montshire Media','A Vancouver agency connecting performance marketing and product engineering.',intro('ABOUT MONTSHIRE MEDIA','Different disciplines.<br>Shared conviction.','The customer journey does not stop at the website. Neither should the thinking behind it.')+'<section class="section split"><h2>Built around<br>the whole picture.</h2><div><p class="lead">Montshire Media brings marketing and engineering under one roof for technology companies building their next stage of growth.</p><p>We believe stronger work starts when acquisition, messaging, product experience and measurement inform one another. Our role is to connect those decisions and make delivery clear.</p></div></section><section class="section green split"><div class="portrait-placeholder">[Founder photo:<br>to be supplied]</div><div><div class="eyebrow">FOUNDER & PRINCIPAL</div><h2>Monica Dhaya</h2><p>[Founder name supplied in the brief — confirm spelling before launch.]</p><p>[Founder bio, experience and credentials: to be supplied and verified.]</p></div></section><section class="section"><h2>What guides the work.</h2><div class="three"><article><h3>Clarity is a deliverable.</h3><p>Make the decision, the owner and the next step visible.</p></article><article><h3>Build with care.</h3><p>Performance, accessibility and maintainability belong in the brief from day one.</p></article><article><h3>Stay accountable.</h3><p>Separate evidence from assumptions. Make room to learn and change course.</p></article></div></section>'+cta())
phases=[('Discover','Understand the business, the buyer and the systems.','Stakeholder conversations, analytics review, technical audit and a documented baseline.'),('Strategy','Choose the work that matters most.','Prioritized roadmap, scope, success measures, responsibilities and dependencies.'),('Build','Deliver in visible increments.','Agreed sprint cadence, working demos, acceptance criteria and issue tracking.'),('Launch','Release with a clear go/no-go decision.','Functional, accessibility, security and performance checks; deployment and rollback plan.'),('Optimize','Turn evidence into the next decision.','Reporting on an agreed cadence, experiment backlog and prioritization review.')]
add('/process/','How we work','Discover, strategize, build, launch and optimize with clear delivery governance.',intro('OUR PROCESS','Momentum needs<br>a method.','A clear route from the first question to the next measurable improvement.')+'<section class="section narrow">'+''.join(f'<article class="phase" id="step-{i}"><div class="eyebrow">0{i}</div><h2>{n}</h2><h3>{h}</h3><p>{d}</p></article>' for i,(n,h,d) in enumerate(phases,1))+'</section><section class="section green"><h2>No surprises by design.</h2><div class="three"><article><h3>Delivery governance</h3><p>Agree sprint length, meeting rhythm and approval owners at kickoff.</p></article><article><h3>Support expectations</h3><p>Response targets, service hours and SLAs are scoped in the engagement agreement.</p></article><article><h3>Quality gates</h3><p>Document acceptance criteria and QA evidence before releasing work.</p></article></div></section>'+cta())
add('/insights/','Insights','Draft perspectives on SEO, paid media and web performance.',intro('THE MONTSHIRE PERSPECTIVE','Better questions.<br>Better decisions.','Practical ideas at the intersection of marketing and engineering. Our first editorial outlines are below.')+'<section class="section three">'+insights()+'</section>'+cta())
for slug,cat,title,desc,sections in articles:
 body=intro(cat+' / DRAFT OUTLINE',title,desc)+'<article class="section narrow"><p class="notice">Editorial draft · Montshire Media editorial team · 2-minute outline · Not a finished article</p>'+''.join(f'<h2>{sections[i]}</h2><p>{sections[i+1]}</p>' for i in range(0,6,2))+'<p>[Add research, original examples, author approval and publication date before publishing.]</p></article><section class="section"><h2>Keep exploring.</h2><div class="three">'+insights()+'</div></section>'
